async function home(){const ls=await api("/listings?sort=new");return `<section class="promo"><div class="pl">${logo(76)}<h1>Всё для твоих любимых игр</h1></div><p>Находи игровые товары и услуги в одном месте.</p><button class="btn pri big" onclick="go('/games')">Перейти к покупкам</button></section><div class="row bet"><h2>Игры</h2><a class="lk" onclick="go('/games')">Все игры</a></div><div class="grid">${GAMES.slice(0,6).map(gp).join("")}</div><h2>Новые предложения</h2>${rows(ls.slice(0,5),"Пока нет опубликованных предложений.")}`}
async function catalog(){PG=0;const ls=await api("/listings?"+qs()),g=GAMES.find(x=>x.slug===F.game),c=CATS.find(x=>x.slug===F.category),open=sessionStorage.fo==="1";
return `<div class="row bet" style="margin:14px 0 8px"><h1 style="font-size:20px">${esc(g?g.name:"Все игры")}${c?" · "+esc(c.name):""}</h1></div><div class="row" style="margin-bottom:10px"><button class="btn sm" onclick="sessionStorage.fo=sessionStorage.fo==='1'?'0':'1';$('#fp').classList.toggle('open')">Фильтры</button>${c?`<button class="btn sm pri" onclick="go('/sell?${new URLSearchParams({game:F.game||"",category:c.slug})}')">${SELL[c.slug]||"Создать объявление"}</button>`:`<button class="btn sm pri" onclick="go('/sell')">Создать объявление</button>`}<select style="width:auto" onchange="F.sort=this.value;go('/catalog?'+qs())">${[["new","Сначала новые"],["cheap","Сначала дешёвые"],["expensive","Сначала дорогие"],["rating","По рейтингу продавца"]].map(o=>`<option value="${o[0]}" ${(F.sort||"new")===o[0]?"selected":""}>${o[1]}</option>`).join("")}</select></div><div id="fp" class="card fpn ${open?"open":""}"><div class="grid">${sel("game",GAMES,"Все игры")}${sel("category",CATS,"Все категории")}<input type="number" min="0" placeholder="Цена от" value="${esc(F.min||"")}" onchange="F.min=this.value;go('/catalog?'+qs())"><input type="number" min="0" placeholder="Цена до" value="${esc(F.max||"")}" onchange="F.max=this.value;go('/catalog?'+qs())"></div><button class="btn sm" style="margin-top:10px" onclick="F={};go('/catalog')">Сбросить</button></div><div id="rl">${rows(ls,"Ничего не найдено. Измените фильтры или запрос.")}</div>${ls.length===50?'<div style="text-align:center"><button class="btn" onclick="more(this)">Показать ещё</button></div>':""}`}
