const vstat=async()=>api("/verify/status");
async function sell(){need();const p=qp(),gs=p.get("game")||"",cs=p.get("category")||"",g=GAMES.find(x=>x.slug===gs),c=CATS.find(x=>x.slug===cs);
if(!ME.is_seller)return `<h2>Продажа</h2><div class="card"><p>Чтобы публиковать объявления, нужен статус продавца.</p><button class="btn pri" onclick="saveMe({is_seller:true})">Стать продавцом</button></div>`;
const v=await vstat();if(v.required&&!v.verified)return verifyBox(v);
const cur=cs==="currency",fl=FLD[cs]||[];
return `<div class="row bet" style="margin:12px 0"><a class="bk" onclick="history.back()">‹</a><h1 style="font-size:19px;flex:1">${SELL[cs]||"Создать объявление"}</h1></div><div class="card lf"><div class="lsec">Что продаёте</div><div class="grid"><div><label>Игра</label>${g?`<input value="${esc(g.name)}" disabled><input type="hidden" id="sg" value="${g.slug}">`:`<select id="sg" oninput="refreshCats()">${GAMES.map(x=>`<option value="${x.slug}">${esc(x.name)}</option>`).join("")}</select>`}</div><div><label>Категория</label>${c?`<input value="${esc(c.name)}" disabled><input type="hidden" id="sc" value="${c.slug}">`:`<select id="sc" oninput="pvw()">${catsOf(gs).map(x=>`<option value="${x.slug}">${esc(x.name)}</option>`).join("")}</select>`}</div></div>
<label>Название</label><input id="st" maxlength="120" oninput="pvw()"><div class="hint">От 5 до 120 символов</div>${fl.length?`<div class="lsec">Параметры</div>`+fl.map(f=>`<label>${f[1]}</label><input data-a="${f[0]}" maxlength="200">`).join(""):""}
<div class="lsec">Описание</div><label>Подробное описание</label><textarea id="sdt" rows="5" maxlength="3000"></textarea><div class="hint">Можно не заполнять. Показывается в блоке «Подробнее»</div><label class="chk"><input type="checkbox" id="sgp"> <span>Разрешить совместную покупку</span></label><div class="hint">Два покупателя смогут скинуться на лот и разделить оплату. Доступно для заказов от 1 000 ₽</div><label class="chk"><input type="checkbox" id="sds" > <span>Деактивировать лот после продажи</span></label><div class="hint">Как только другой пользователь оплатит заказ, объявление уйдёт в архив. Без галочки лот остаётся в продаже, пока есть остаток.</div><label>Сообщение покупателю после оплаты</label><textarea id="sam" rows="4" maxlength="2000"></textarea><div class="hint">Можно не заполнять. Увидит только покупатель после оплаты, в объявлении не публикуется</div><label>Срок выполнения</label><input id="sd" maxlength="40" placeholder="например, 15 минут" oninput="pvw()">
<div class="lsec">Цена и наличие</div><label>${cur?"Цена за 1 шт.":"Цена"}</label><div class="sf"><input id="sp" type="number" min="0.01" step="0.01" inputmode="decimal" oninput="pvw()"><span>₽</span></div><label>Наличие</label><div class="sf"><input id="ss" type="number" min="1" value="1" inputmode="numeric" oninput="pvw()"><span>шт.</span></div>
<div class="lsec">Изображение</div><input id="si2" type="file" accept="image/png,image/jpeg,image/webp"><div class="hint">png, jpeg или webp до 1 МБ</div><p class="m"><small>Не указывайте пароли, коды и другие секретные данные в описании: оно публичное. Данные для входа передавайте в чате заказа или в сообщении после оплаты.</small></p></div><h3>Предпросмотр</h3><div class="card" id="pv"></div><button class="btn pri big" style="width:100%" onclick="createL2()">Отправить на модерацию</button>`}
function pvw(){const p=$("#pv");if(!p)return;const g=GAMES.find(x=>x.slug===$("#sg").value),c=CATS.find(x=>x.slug===$("#sc").value);p.innerHTML=row({id:"x",game_name:g?.name||"",category_name:c?.name||"",title:$("#st").value||"Название",summary:($("#sm")||{}).value||"",seller:ME.username,rating:null,reviews:0,delivery_time:$("#sd").value,stock:+$("#ss").value||1,price_cents:Math.round(+$("#sp").value*100)||0}).replace(/onclick="[^"]*"/g,"")}
const upload=async(file,kind)=>{const OK=["image/png","image/jpeg","image/webp"].concat(kind==="cover"||kind==="news"?["image/gif"]:[]),max={avatar:1e6,cover:2e6,listing:1e6,news:2e6}[kind];if(!OK.includes(file.type))throw new Error("Допустимы png, jpeg, webp"+(kind==="cover"||kind==="news"?", gif":""));if(file.size>max)throw new Error("Файл слишком большой (максимум "+max/1e6+" МБ)");const r=await fetch("/api/media?kind="+kind,{method:"POST",headers:{"Content-Type":"application/octet-stream"},body:file,credentials:"same-origin"});const d=await r.json();if(!r.ok)throw new Error(d.error||"Ошибка загрузки");return d.id};
const createL2=act(async()=>{const price=+$("#sp").value,stock=+$("#ss").value,t=$("#st").value.trim();if(t.length<5)throw new Error("Название: минимум 5 символов");if(!(price>0))throw new Error("Укажите цену больше нуля");if(!Number.isInteger(stock)||stock<1)throw new Error("Количество: целое число от 1");
const attrs={};document.querySelectorAll("[data-a]").forEach(i=>{if(i.value.trim())attrs[i.dataset.a]=i.value.trim()});const f=$("#si2").files[0],image=f?await upload(f,"listing"):undefined;
const r=await api("/listings",{method:"POST",body:{game:$("#sg").value,category:$("#sc").value,title:t,price,stock,delivery_time:$("#sd").value,summary:($("#sm")||{}).value||"",details:$("#sdt").value,after_msg:($("#sam")||{}).value||"",allow_group:!!$("#sgp")?.checked,deactivate_on_sale:!!$("#sds")?.checked,auto_items:window._auto&&window._auto.items&&window._auto.items.length?window._auto.items:undefined,attrs,image}});toast("Отправлено на модерацию");go("/l/"+r.id)});
function verifyBox(v){return `<h2>Верификация продавца</h2><div class="vstack">${v.verified?`<div class="card"><b>Верификация пройдена</b><p class="m" style="margin:6px 0 0">Вы можете создавать объявления.</p><button class="btn pri wr" style="margin-top:10px" onclick="go('/sell')">Создать объявление</button></div>`:!v.configured?`<div class="card"><b>Верификация временно недоступна</b><p class="m">Telegram-бот не настроен на сервере. Не хватает переменных окружения:</p><ul>${(v.missing||[]).map(x=>`<li><code>${esc(x)}</code></li>`).join("")}</ul></div>`:`<div class="card"><b>Подтвердите Telegram</b><p class="m" style="margin:6px 0">Номер телефона не показывается другим пользователям, сохраняются только последние 4 цифры.</p><ol class="m"><li>Нажмите кнопку ниже: откроется Telegram-бот.</li><li>Нажмите «Старт» и поделитесь своим контактом кнопкой.</li><li>Вернитесь на сайт: статус обновится.</li></ol></div><div class="card"><button class="btn pri wr" style="width:100%" onclick="startV()">Перейти к Telegram-боту</button><button class="btn wr" style="width:100%;margin-top:8px" onclick="checkV()">Я подтвердил, проверить статус</button></div>`}</div>`}
const startV=act(async()=>{const r=await api("/verify/start",{method:"POST"});location.href=r.url}),checkV=act(async()=>{ME=await api("/me");const v=await vstat();toast(v.verified?"Верификация пройдена":"Пока не подтверждено в боте");route()});
async function verify(){need();return verifyBox(await vstat())+`<div class="card" style="margin-top:12px"><b>Кодекс продавца</b><p class="m" style="margin:6px 0 10px">Правила, которые продавец публично обязуется соблюдать. Подписанный кодекс обязателен для публикации лотов.</p><button class="btn wr" style="width:100%" onclick="go('/code')">Открыть Кодекс продавца</button></div>`}
document.addEventListener("visibilitychange",()=>{if(!document.hidden&&location.hash.startsWith("#/verify")&&ME)checkV()});
