const h=`/u/${encodeURIComponent(u.username)}`,body=tab==="reviews"?(rv.map(r=>`<div class="card"><b>★${r.rating}</b> ${esc(r.reviewer)} <small class="m">${new Date(r.created_at).toLocaleDateString("ru-RU")}</small><div class="m">${esc(r.body||"")}</div>${r.reply?`<div class="rrp"><b>Ответ продавца</b><p>${esc(r.reply)}</p></div>`:""}</div>`).join("")||empty("Отзывов пока нет.")):tab==="about"?`<div class="card"><p>${esc(u.bio||"Пользователь пока ничего не рассказал о себе.")}</p><p class="m">На сайте с ${new Date(u.created_at).toLocaleDateString("ru-RU")}</p></div>${aboutExtra(u,cs)}`:rows(ls,"Нет активных объявлений.");
