// ---- документы (черновики)
const FILL=t=>`<mark>[${t}]</mark>`;
const LEG={privacy:["Политика конфиденциальности",`<p><b>Черновик для проверки юристом перед публикацией.</b> Это не юридическая гарантия соответствия законодательству какой-либо страны.</p><h3>1. Оператор</h3><p>Оператор: ${FILL("название или ФИО оператора")}, адрес: ${FILL("адрес")}, контакт по вопросам данных: ${FILL("email")}.</p><h3>2. Какие данные мы обрабатываем</h3><p>Данные аккаунта (email, имя пользователя, хэш пароля, роль); оформление профиля и загруженные изображения; объявления; заказы и их статусы; сообщения между пользователями; обращения в поддержку и споры; технические данные (IP-адрес, сведения о браузере в серверных журналах); при верификации продавца через Telegram: Telegram ID и последние 4 цифры номера телефона (номер целиком не сохраняется).</p><h3>3. Цели</h3><p>Работа маркетплейса, исполнение заказов, связь между пользователями, модерация и защита от мошенничества, поддержка, выполнение требований закона.</p><h3>4. Основания</h3><p>${FILL("основание: договор / согласие / законный интерес, определить после выбора страны оператора")}.</p><h3>5. Сроки хранения</h3><p>${FILL("сроки по каждой категории данных")}.</p><h3>6. Защита</h3><p>Пароли хранятся в виде хэшей, доступ к данным ограничен ролями, административные действия записываются в журнал. Абсолютную защиту мы не гарантируем.</p><h3>7. Передача третьим лицам</h3><p>Telegram (верификация), хостинг и база данных ${FILL("провайдеры")}, платёжный провайдер после его подключения ${FILL("провайдер")}.</p><h3>8. Ваши права и обращения</h3><p>Запросы на доступ, исправление и удаление данных: ${FILL("email")}. Применимые права зависят от вашей страны ${FILL("уточнить после определения страны оператора и аудитории")}.</p>`],terms:["Пользовательское соглашение",`<p><b>Черновик.</b> Оператор: ${FILL("оператор")}.</p><p>DonutPay предоставляет площадку, где пользователи публикуют объявления и заключают сделки между собой. Оплата в сервисе пока не подключена; пока это не появится, платёжных операций и удержания средств нет. Пользователь отвечает за достоверность объявлений и соблюдение правил игр и платформ. Оператор может скрывать объявления и блокировать аккаунты за нарушения. Ответственность и порядок споров: ${FILL("уточнить")}.</p>`],rules:["Правила маркетплейса",`<p><b>Черновик.</b> Запрещено: мошенничество, продажа запрещённых правилами игры товаров, публикация чужих данных, обход площадки. Споры рассматривает поддержка: открыть спор можно в заказе. Пока оплата не подключена, возвраты денег не выполняются. ${FILL("дополнить правилами")}</p>`],"seller-rules":["Правила продавцов",`<p><b>Черновик.</b> Продавец подтверждает контакт через Telegram-бота перед первым объявлением. Объявления проходят модерацию. Нельзя публиковать пароли и секретные данные в объявлении. Выполняйте заказ в указанный срок. ${FILL("комиссии, штрафы, сроки выплат после подключения оплаты")}</p>`],contacts:["Контакты",`<p>Email: ${FILL("email оператора")}</p><p>Telegram: ${FILL("контакт")}</p><p>Оператор: ${FILL("название и адрес")}</p><p>Вопросы по заказам: <a class="lk" onclick="go('/tickets?new=1')">написать в поддержку</a>.</p>`]};
